{
  "name": "Newport 1830C光功率计",
  "name_en": "Newport 1830C Optical Power Meter",
  "manufacturer": "Newport",
  "description": "这是一款用于测量光功率的台式光功率计，可通过串口进行远程控制，读取功率数据，并设置波长、量程、平均滤波、归零、参考值以及前面板相关参数，适用于激光与光学实验中的功率监测和校准。",
  "description_en": "This is a benchtop optical power meter for measuring optical power. It supports remote serial control to read power data and configure wavelength, measurement range, averaging filter, zeroing, reference level, and front-panel settings, making it suitable for power monitoring and calibration in laser and optical experiments.",
  "actions": [
    {
      "action_name": "auto-autocalibration_async",
      "description": "异步执行功率计自动校准，校准时会断开输入信号。",
      "description_en": "Asynchronously perform the power meter auto-calibration, which disconnects the input signal during calibration."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化光功率计并建立串口通信。",
      "description_en": "Initialize the optical power meter and establish serial communication."
    },
    {
      "action_name": "auto-store_reference_async",
      "description": "异步将当前输入光功率保存为参考功率值。",
      "description_en": "Asynchronously store the current input optical power as the reference power level."
    },
    {
      "action_name": "auto-attenuator",
      "description": "读取或设置衰减器状态/存在情况。",
      "description_en": "Get or set the attenuator status/presence."
    },
    {
      "action_name": "auto-beeper",
      "description": "读取或设置蜂鸣提示音开关。",
      "description_en": "Get or set the beeper on/off state."
    },
    {
      "action_name": "auto-data",
      "description": "读取当前光功率测量值。",
      "description_en": "Read the current optical power measurement value."
    },
    {
      "action_name": "auto-echo",
      "description": "读取或设置RS232回显模式。",
      "description_en": "Get or set the RS232 echo mode."
    },
    {
      "action_name": "auto-filter",
      "description": "读取或设置测量平均滤波速度。",
      "description_en": "Get or set the measurement averaging filter speed."
    },
    {
      "action_name": "auto-go",
      "description": "读取或设置是否允许功率计进行新测量。",
      "description_en": "Get or set whether the power meter is allowed to take new measurements."
    },
    {
      "action_name": "auto-keypad",
      "description": "读取或设置按键区/显示背光亮度。",
      "description_en": "Get or set the keypad/display backlight intensity."
    },
    {
      "action_name": "auto-lockout",
      "description": "读取或设置前面板按键锁定状态。",
      "description_en": "Get or set the front-panel key lockout state."
    },
    {
      "action_name": "auto-autocalibration",
      "description": "执行功率计自动校准，校准时会断开输入信号。",
      "description_en": "Perform the power meter auto-calibration, which disconnects the input signal during calibration."
    },
    {
      "action_name": "auto-range",
      "description": "读取或设置输入信号测量量程，可使用自动量程。",
      "description_en": "Get or set the input signal measurement range, including auto-ranging."
    },
    {
      "action_name": "auto-store_reference",
      "description": "将当前输入光功率保存为参考功率值。",
      "description_en": "Store the current input optical power as the reference power level."
    },
    {
      "action_name": "auto-units",
      "description": "读取或设置测量单位。",
      "description_en": "Get or set the measurement units."
    },
    {
      "action_name": "auto-wavelength",
      "description": "读取或设置输入光信号波长。",
      "description_en": "Get or set the input optical signal wavelength."
    },
    {
      "action_name": "auto-zero",
      "description": "读取或设置归零功能，以扣除背景功率。",
      "description_en": "Get or set the zero function to subtract background power."
    }
  ],
  "tag_hints": [
    "optical power measurement",
    "laser power meter",
    "wavelength compensation",
    "auto ranging",
    "zero/background subtraction",
    "reference power level",
    "serial instrument control"
  ]
}

